// servisler.json içindeki listeyi tek tek yoklanacak öğelere çevirir.
// Okuma zinciri hata verdiyse: dosya bozuk/erişilemez ise çalışma durdurulur —
// aksi hâlde liste boş sanılıp üzerine yazılır ve takip listesi kaybolur.
const okuHata = $('Servisleri Oku').first().json.error;
const okuMesaj = okuHata ? String(okuHata.message || okuHata) : '';
const dosyaYok = /ENOENT|no such file|not found/i.test(okuMesaj);
const cikarHata = $('Servisleri Çıkar').first().json.error;
if (!dosyaYok && (okuHata || cikarHata)) {
  const m = okuMesaj || String((cikarHata && cikarHata.message) || cikarHata);
  throw new Error('servisler.json okunamadı; veri kaybını önlemek için durduruldu → ' + m);
}
if (dosyaYok) {
  throw new Error('local-files/servisler.json yok. Kurulum: cp local-files/servisler.ornek.json local-files/servisler.json');
}

const j = $input.first().json || {};
const ham = (j.data && j.data.servisler) || j.servisler || [];
const servisler = (Array.isArray(ham) ? ham : [])
  .filter((s) => s && typeof s.url === 'string' && /^https?:\/\//i.test(s.url.trim()))
  .map((s) => ({
    ad: String(s.ad || s.url).trim(),
    url: s.url.trim(),
    yontem: String(s.yontem || 'GET').toUpperCase(),
    beklenenKod: Number(s.beklenenKod) || 200,
    icerir: String(s.icerir || ''),
    zamanAsimi: Number(s.zamanAsimi) || 15000,
    esik: Math.max(1, Number(s.esik) || 2),
    sonDurum: s.sonDurum || null,
    sonKod: typeof s.sonKod === 'number' ? s.sonKod : null,
    sonHata: s.sonHata || null,
    sonKontrol: s.sonKontrol || null,
    ardArda: Number(s.ardArda) || 0,
    ilkHata: s.ilkHata || null,
    uyarildi: Boolean(s.uyarildi),
  }));

if (servisler.length === 0) {
  throw new Error('servisler.json içinde geçerli servis yok — her kaydın "url" alanı http:// veya https:// ile başlamalı.');
}
return servisler.map((s) => ({ json: s }));

// Yoklama sonuçlarını önceki durumla karşılaştırır.
// Bildirim YALNIZCA durum değişince gider: bir servis düştüğünde bir kez,
// düzeldiğinde bir kez. Kapalı servis her turda tekrar yazmaz.
const esc = (s) => String(s ?? '').replace(/[&<>]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
const kisalt = (s, n = 140) => {
  const t = String(s || '').replace(/\s+/g, ' ').trim();
  return t.length > n ? t.slice(0, n) + '…' : t;
};
const sureMetni = (ms) => {
  const dk = Math.max(1, Math.round(ms / 60000));
  if (dk < 60) return dk + ' dk';
  const sa = Math.floor(dk / 60);
  if (sa < 24) return sa + ' sa ' + (dk % 60) + ' dk';
  return Math.floor(sa / 24) + ' gün ' + (sa % 24) + ' sa';
};

const servisler = $('Servisleri Listele').all().map((x) => ({ ...x.json }));
const sonuclar = $input.all();
const simdi = new Date();
const dusenler = [];
const duzelenler = [];

for (let i = 0; i < servisler.length; i++) {
  const s = servisler[i];
  const r = (sonuclar[i] && sonuclar[i].json) || {};
  const hataMetni = r.error ? kisalt(r.error.message || r.error) : '';
  const kod = Number(r.statusCode || 0);
  const govde = typeof r.body === 'string' ? r.body : (r.body ? JSON.stringify(r.body) : '');

  let sorun = '';
  if (hataMetni) {
    sorun = /timeout|ETIMEDOUT|ESOCKETTIMEDOUT/i.test(hataMetni) ? 'yanıt vermedi (zaman aşımı)'
      : /ENOTFOUND|EAI_AGAIN|getaddrinfo/i.test(hataMetni) ? 'adres çözülemedi (DNS)'
      : /ECONNREFUSED/i.test(hataMetni) ? 'bağlantı reddedildi (servis kapalı olabilir)'
      : /certificate|CERT_|SSL|TLS/i.test(hataMetni) ? 'TLS/sertifika hatası: ' + hataMetni
      : hataMetni;
  } else if (!kod) {
    sorun = 'yanıt alınamadı';
  } else if (kod !== s.beklenenKod) {
    sorun = 'HTTP ' + kod + ' döndü (beklenen ' + s.beklenenKod + ')';
  } else if (s.icerir && !govde.includes(s.icerir)) {
    sorun = '"' + kisalt(s.icerir, 40) + '" metni yanıtta yok';
  }

  s.sonKontrol = simdi.toISOString();
  s.sonKod = kod || null;

  if (!sorun) {
    if (s.uyarildi) {
      const sure = s.ilkHata ? simdi.getTime() - new Date(s.ilkHata).getTime() : 0;
      duzelenler.push({ ad: s.ad, url: s.url, sure: sureMetni(sure) });
    }
    s.sonDurum = 'ayakta';
    s.sonHata = null;
    s.ardArda = 0;
    s.ilkHata = null;
    s.uyarildi = false;
  } else {
    s.sonDurum = 'kapali';
    s.sonHata = sorun;
    s.ardArda = (Number(s.ardArda) || 0) + 1;
    if (!s.ilkHata) s.ilkHata = simdi.toISOString();
    if (!s.uyarildi && s.ardArda >= s.esik) {
      s.uyarildi = true;
      dusenler.push({ ad: s.ad, url: s.url, sorun, deneme: s.ardArda });
    }
  }
}

const satirlar = [];
const htmlBolum = [];
for (const d of dusenler) {
  satirlar.push('🔴 ' + d.ad + ' KAPALI\n   ' + d.sorun + '\n   ' + d.url);
  htmlBolum.push('<li style="margin:6px 0"><b>🔴 ' + esc(d.ad) + ' kapalı</b><br>' + esc(d.sorun) +
    '<br><a href="' + esc(d.url) + '">' + esc(d.url) + '</a></li>');
}
for (const d of duzelenler) {
  satirlar.push('✅ ' + d.ad + ' yeniden ayakta (' + d.sure + ' kapalı kaldı)');
  htmlBolum.push('<li style="margin:6px 0"><b>✅ ' + esc(d.ad) + ' yeniden ayakta</b><br>' +
    esc(d.sure) + ' kapalı kaldı</li>');
}

const kapali = servisler.filter((s) => s.sonDurum === 'kapali').length;
const ayakta = servisler.length - kapali;
const text = satirlar.length
  ? satirlar.join('\n\n') + '\n\n— ' + ayakta + ' ayakta, ' + kapali + ' kapalı'
  : '';
const html = htmlBolum.length
  ? '<div style="font-family:sans-serif;max-width:640px"><h2>🩺 Servis durumu</h2><ul style="list-style:none;padding:0">' +
    htmlBolum.join('') + '</ul><p style="color:#999">' + ayakta + ' ayakta, ' + kapali + ' kapalı</p></div>'
  : '';
const konu = dusenler.length
  ? '[n8n] 🔴 ' + (dusenler.length === 1 ? dusenler[0].ad + ' kapalı' : dusenler.length + ' servis kapalı')
  : duzelenler.length
    ? '[n8n] ✅ ' + (duzelenler.length === 1 ? duzelenler[0].ad + ' yeniden ayakta' : duzelenler.length + ' servis düzeldi')
    : '';

return [{
  json: {
    servisler,
    gonderilecek: satirlar.length > 0,
    yazilsin: true,
    text,
    html,
    konu,
    dusen: dusenler.length,
    duzelen: duzelenler.length,
    ayakta,
    kapali,
  },
}];

// Telegram kuruluysa uyarı oraya gider; değilse bu dal boş döner.
const token = String($env.TELEGRAM_BOT_TOKEN || '').trim();
const chat = String($env.TELEGRAM_CHAT_ID || '').trim();
if (!token || !chat) return [];
return [{ json: { chat_id: chat, text: ('🩺 ' + $input.first().json.text).slice(0, 3900) } }];

// Telegram kurulu DEĞİLSE uyarı mail olarak gider (çift bildirim olmasın).
const kurulu = String($env.TELEGRAM_BOT_TOKEN || '').trim() && String($env.TELEGRAM_CHAT_ID || '').trim();
if (kurulu) return [];
const j = $input.first().json;
return [{ json: { konu: j.konu, html: j.html } }];

// Dosyaya yalnızca servis listesi (güncel durumlarıyla) yazılır.
const j = $input.first().json;
if (!j.yazilsin) return [];
return [{ json: { servisler: j.servisler } }];

// Telegram'dan /servis komutu gelince son bilinen durumu özetler.
// Yeni yoklama YAPMAZ — zamanlanmış kontrolün en son yazdığı bilgiyi okur.
const cagri = $('Workflow 05\'ten Çağrı (Servis)').first().json || {};
const okuHata = $('Servisleri Oku (Durum)').first().json.error;
const okuMesaj = okuHata ? String(okuHata.message || okuHata) : '';
const cikarHata = $('Servisleri Çıkar (Durum)').first().json.error;

const chat = cagri.chat_id ? String(cagri.chat_id) : '';
if (!chat) return [];

if (okuHata || cikarHata) {
  const dosyaYok = /ENOENT|no such file|not found/i.test(okuMesaj);
  return [{ json: { chat_id: chat, text: dosyaYok
    ? '🩺 Takip listesi yok. Kurulum: cp local-files/servisler.ornek.json local-files/servisler.json'
    : '🩺 servisler.json okunamadı: ' + (okuMesaj || 'bozuk dosya') } }];
}

const j = $input.first().json || {};
const ham = (j.data && j.data.servisler) || j.servisler || [];
const servisler = Array.isArray(ham) ? ham : [];
if (servisler.length === 0) {
  return [{ json: { chat_id: chat, text: '🩺 Takip listesi boş. local-files/servisler.json dosyasına servis ekleyin.' } }];
}

const gecen = (iso) => {
  if (!iso) return 'hiç kontrol edilmedi';
  const dk = Math.round((Date.now() - new Date(iso).getTime()) / 60000);
  if (!Number.isFinite(dk)) return 'bilinmiyor';
  if (dk < 1) return 'az önce';
  if (dk < 60) return dk + ' dk önce';
  const sa = Math.floor(dk / 60);
  return sa < 24 ? sa + ' sa önce' : Math.floor(sa / 24) + ' gün önce';
};

const satirlar = servisler.map((s) => {
  const ad = s.ad || s.url;
  if (s.sonDurum === 'kapali') {
    return '🔴 ' + ad + ' — ' + (s.sonHata || 'kapalı') + ' (' + (Number(s.ardArda) || 1) + '. tur)';
  }
  if (s.sonDurum === 'ayakta') return '✅ ' + ad + ' — HTTP ' + (s.sonKod || 200);
  return '⬜ ' + ad + ' — henüz kontrol edilmedi';
});

const enSon = servisler
  .map((s) => s.sonKontrol)
  .filter(Boolean)
  .sort()
  .pop();

return [{ json: {
  chat_id: chat,
  text: ('🩺 Servis durumu\n' + satirlar.join('\n') + '\n\nSon kontrol: ' + gecen(enSon)).slice(0, 3900),
} }];
